const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for both islands
  // Robinson Crusoe Island (main island, larger)
  const robinsonCrusoe = ee.Geometry.Point([-78.85, -33.64]);

  // Santa Clara Island (small islet to the southwest)
  const santaClara = ee.Geometry.Point([-78.97, -33.69]);

  const startDate = '2018-11-01';
  const endDate = '2018-11-30';

  // 2. Try Sentinel-2 first
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(robinsonCrusoe)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(santaClara)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Robinson Crusoe S2 images: ${size1}`);
  console.log(`Santa Clara S2 images: ${size2}`);

  // Fallback to Landsat 8 if Sentinel-2 fails
  if (size1 === 0 || size2 === 0) {
    console.log('Trying Landsat 8 fallback...');
    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(robinsonCrusoe)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(santaClara)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    const l8size1 = await col1.size().getInfo();
    const l8size2 = await col2.size().getInfo();

    console.log(`Robinson Crusoe L8 images: ${l8size1}`);
    console.log(`Santa Clara L8 images: ${l8size2}`);

    if (l8size1 === 0 || l8size2 === 0) {
      console.log('No images available for one or both locations');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Cloud masking and NDVI calculation
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask)
      .normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  function maskL8clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask)
      .normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  }

  let ndvi1, ndvi2;

  if (size1 > 0) {
    ndvi1 = col1.map(maskS2clouds).median();
    ndvi2 = col2.map(maskS2clouds).median();
  } else {
    ndvi1 = col1.map(maskL8clouds).median();
    ndvi2 = col2.map(maskL8clouds).median();
  }

  // 4. Calculate mean NDVI and pixel counts
  const buffer1 = robinsonCrusoe.buffer(1000);
  const buffer2 = santaClara.buffer(500);

  const stats1 = await ndvi1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer1,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await ndvi2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer2,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.NDVI_mean;
  const count1 = stats1.NDVI_count;
  const mean2 = stats2.NDVI_mean;
  const count2 = stats2.NDVI_count;

  console.log(`Robinson Crusoe: NDVI=${mean1?.toFixed(3)}, Pixels=${count1}`);
  console.log(`Santa Clara: NDVI=${mean2?.toFixed(3)}, Pixels=${count2}`);

  // 5. Validation and answer
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean1 === null || mean2 === null || 
      mean1 === undefined || mean2 === undefined ||
      isNaN(mean1) || isNaN(mean2) ||
      mean1 < -1 || mean1 > 1 || mean2 < -1 || mean2 > 1) {
    console.log('Invalid NDVI values calculated');
    console.log('<answer>C3</answer>');
    return;
  }

  if (mean1 > mean2) {
    console.log('Robinson Crusoe shows higher greenness');
    console.log('<answer>A</answer>');
  } else {
    console.log('Robinson Crusoe does not show higher greenness');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
